import { createServer, type IncomingMessage, type ServerResponse } from 'node:http';
import { readFileSync } from 'node:fs';
import { randomUUID } from 'node:crypto';
import { openDatabase, asJob, type JobRow } from './db.ts';

const db = openDatabase();
const uiHtml = readFileSync(new URL('../ui/index.html', import.meta.url), 'utf8');
function send(res: ServerResponse, status: number, body: unknown): void {
  res.writeHead(status, { 'content-type': 'application/json; charset=utf-8' });
  res.end(JSON.stringify(body));
}
function error(res: ServerResponse, status: number, code: string, message: string, fields?: { field: string; message: string }[]): void {
  send(res, status, { error: { code, message, ...(fields ? { fields } : {}) } });
}
function bad(res: ServerResponse, fields: { field: string; message: string }[]): void {
  error(res, 400, 'invalid_request', 'The request is invalid.', fields);
}
async function readBody(req: IncomingMessage): Promise<string> {
  let body = ''; for await (const chunk of req) { body += chunk.toString(); if (body.length > 100_000) throw new Error('too_large'); }
  return body;
}
const server = createServer(async (req, res) => {
  const { pathname } = new URL(req.url ?? '/', 'http://localhost');
  if (pathname === '/' && req.method === 'GET') {
    res.writeHead(200, { 'content-type': 'text/html; charset=utf-8' }); res.end(uiHtml); return;
  }
  const apiKnown = pathname === '/health' || pathname === '/' || pathname === '/api/jobs' || /^\/api\/jobs\/[^/]+$/.test(pathname);
  if (pathname === '/health') {
    if (req.method !== 'GET') return error(res, 405, 'method_not_allowed', 'Method not allowed.');
    const heartbeat = db.prepare('SELECT seen_at FROM worker_heartbeat WHERE id = 1').get() as { seen_at: number } | undefined;
    return send(res, 200, { status: 'ok', worker: heartbeat && Date.now() - heartbeat.seen_at < 3000 ? 'up' : 'down' });
  }
  if (pathname === '/api/jobs' && req.method === 'GET') {
    const rows = db.prepare('SELECT * FROM jobs ORDER BY created_at DESC, rowid DESC').all() as unknown as JobRow[];
    return send(res, 200, { jobs: rows.map(asJob) });
  }
  if (pathname === '/api/jobs' && req.method === 'POST') {
    const fields: { field: string; message: string }[] = [];
    const contentType = req.headers['content-type'] ?? '';
    if (!/^application\/json(?:\s*;|\s*$)/i.test(contentType)) { bad(res, [{ field: 'Content-Type', message: 'Must be application/json.' }]); return; }
    let raw: string;
    try { raw = await readBody(req); } catch { bad(res, [{ field: 'body', message: 'Body is too large or unreadable.' }]); return; }
    let body: unknown;
    try { body = JSON.parse(raw); } catch { bad(res, [{ field: 'body', message: 'Must be valid JSON.' }]); return; }
    if (!body || typeof body !== 'object' || Array.isArray(body)) { bad(res, [{ field: 'body', message: 'Must be a JSON object.' }]); return; }
    const obj = body as Record<string, unknown>;
    for (const k of Object.keys(obj)) if (!['input', 'steps', 'failAttempts'].includes(k)) fields.push({ field: k, message: 'Unknown field.' });
    if (typeof obj.input !== 'string') fields.push({ field: 'input', message: 'Must be a string.' });
    else if (obj.input.length < 1 || obj.input.length > 1000 || obj.input.trim().length === 0) fields.push({ field: 'input', message: 'Must contain 1 to 1000 non-whitespace characters.' });
    const steps = obj.steps === undefined ? 5 : obj.steps;
    const failAttempts = obj.failAttempts === undefined ? 0 : obj.failAttempts;
    if (!Number.isInteger(steps) || (steps as number) < 1 || (steps as number) > 20) fields.push({ field: 'steps', message: 'Must be an integer from 1 to 20.' });
    if (!Number.isInteger(failAttempts) || (failAttempts as number) < 0 || (failAttempts as number) > 5) fields.push({ field: 'failAttempts', message: 'Must be an integer from 0 to 5.' });
    const key = req.headers['idempotency-key'];
    if (Array.isArray(key) || (key !== undefined && !/^[A-Za-z0-9_-]{1,128}$/.test(key))) fields.push({ field: 'Idempotency-Key', message: 'Must contain 1 to 128 letters, numbers, underscores, or hyphens.' });
    if (fields.length) { bad(res, fields); return; }
    const idempotencyKey = typeof key === 'string' ? key : undefined;
    const normalized = { input: obj.input as string, steps: steps as number, failAttempts: failAttempts as number };
    const payload = JSON.stringify(normalized);
    if (idempotencyKey !== undefined) {
      const existing = db.prepare('SELECT * FROM jobs WHERE idempotency_key = ?').get(idempotencyKey) as unknown as (JobRow & { idempotency_payload: string }) | undefined;
      if (existing) {
        if (existing.idempotency_payload !== payload) return error(res, 409, 'idempotency_conflict', 'This Idempotency-Key was used with a different payload.');
        return send(res, 200, asJob(existing));
      }
    }
    const now = new Date().toISOString(), id = randomUUID();
    try {
      db.prepare('INSERT INTO jobs (id,status,input,steps,fail_attempts,attempts,progress_completed,created_at,updated_at,idempotency_key,idempotency_payload) VALUES (?,\'queued\',?,?,?,0,0,?,?,?,?)')
        .run(id, normalized.input, normalized.steps, normalized.failAttempts, now, now, idempotencyKey ?? null, idempotencyKey === undefined ? null : payload);
    } catch (e) {
      // Concurrent identical submissions can race after the initial lookup.
      if (idempotencyKey !== undefined) {
        const existing = db.prepare('SELECT * FROM jobs WHERE idempotency_key = ?').get(idempotencyKey) as unknown as (JobRow & { idempotency_payload: string }) | undefined;
        if (existing) return existing.idempotency_payload === payload ? send(res, 200, asJob(existing)) : error(res, 409, 'idempotency_conflict', 'This Idempotency-Key was used with a different payload.');
      }
      throw e;
    }
    const row = db.prepare('SELECT * FROM jobs WHERE id = ?').get(id) as unknown as JobRow;
    return send(res, 201, asJob(row));
  }
  const match = pathname.match(/^\/api\/jobs\/([^/]+)$/);
  if (match) {
    if (req.method !== 'GET') return error(res, 405, 'method_not_allowed', 'Method not allowed.');
    let id: string;
    try { id = decodeURIComponent(match[1]!); } catch { return error(res, 404, 'not_found', 'Job not found.'); }
    const row = db.prepare('SELECT * FROM jobs WHERE id = ?').get(id) as unknown as JobRow | undefined;
    return row ? send(res, 200, asJob(row)) : error(res, 404, 'not_found', 'Job not found.');
  }
  if (apiKnown) return error(res, 405, 'method_not_allowed', 'Method not allowed.');
  return error(res, 404, 'not_found', 'Route not found.');
});
const port = Number(process.env.PORT ?? 3000);
server.listen(port, () => console.log(`server listening on ${port}`));
function stop(): void { server.close(() => { db.close(); }); }
process.on('SIGTERM', stop); process.on('SIGINT', stop);

