import { DatabaseSync } from 'node:sqlite';
import { mkdirSync } from 'node:fs';
import { dirname } from 'node:path';

/** Opens the SQLite database shared by the server and worker processes. */
export function openDatabase(path: string = process.env.DATABASE_PATH ?? 'data/jobs.db'): DatabaseSync {
  if (path !== ':memory:') mkdirSync(dirname(path), { recursive: true });
  const db = new DatabaseSync(path);
  // busy_timeout first: switching to WAL takes a brief exclusive lock, and the server and worker
  // open the same database at once, so the loser must wait rather than fail.
  db.exec(`PRAGMA busy_timeout = 5000; PRAGMA journal_mode = WAL;
    CREATE TABLE IF NOT EXISTS jobs (
      id TEXT PRIMARY KEY, status TEXT NOT NULL, input TEXT NOT NULL,
      steps INTEGER NOT NULL, fail_attempts INTEGER NOT NULL, attempts INTEGER NOT NULL DEFAULT 0,
      progress_completed INTEGER NOT NULL DEFAULT 0, result TEXT, error TEXT,
      created_at TEXT NOT NULL, updated_at TEXT NOT NULL, retry_at INTEGER NOT NULL DEFAULT 0,
      idempotency_key TEXT UNIQUE, idempotency_payload TEXT
    );
    CREATE INDEX IF NOT EXISTS jobs_queue ON jobs(status, created_at);
    CREATE TABLE IF NOT EXISTS worker_heartbeat (id INTEGER PRIMARY KEY CHECK (id = 1), seen_at INTEGER NOT NULL);
  `);
  return db;
}

export interface JobRow {
  id: string; status: 'queued' | 'running' | 'completed' | 'failed'; input: string;
  steps: number; fail_attempts: number; attempts: number; progress_completed: number;
  result: string | null; error: string | null; created_at: string; updated_at: string;
}

export function asJob(row: JobRow): unknown {
  return {
    id: row.id, status: row.status, input: row.input, steps: row.steps,
    failAttempts: row.fail_attempts, attempts: row.attempts,
    progress: { completed: row.progress_completed, total: row.steps },
    result: row.result === null ? null : JSON.parse(row.result), error: row.error,
    createdAt: row.created_at, updatedAt: row.updated_at,
  };
}

