import { setTimeout as sleep } from 'node:timers/promises';
import { openDatabase, type JobRow } from './db.ts';

const db = openDatabase();
let stopping = false;
for (const signal of ['SIGINT', 'SIGTERM'] as const) process.on(signal, () => { stopping = true; });

// A running row belongs to a worker that no longer exists. Count its interrupted
// attempt and put it back in the durable queue, or finish its retry budget.
const nowIso = new Date().toISOString();
db.prepare(`UPDATE jobs SET status='failed', error='transient failure', result=NULL,
  updated_at=?, progress_completed=0 WHERE status='running' AND attempts >= 3`).run(nowIso);
db.prepare(`UPDATE jobs SET status='queued', updated_at=?, progress_completed=0, retry_at=0
  WHERE status='running' AND attempts < 3`).run(nowIso);

function heartbeat(): void {
  db.prepare('INSERT INTO worker_heartbeat (id,seen_at) VALUES (1,?) ON CONFLICT(id) DO UPDATE SET seen_at=excluded.seen_at').run(Date.now());
}
function takeJob(): JobRow | undefined {
  const row = db.prepare(`SELECT * FROM jobs WHERE status='queued' AND retry_at <= ? ORDER BY created_at ASC, rowid ASC LIMIT 1`).get(Date.now()) as unknown as JobRow | undefined;
  if (!row) return undefined;
  const now = new Date().toISOString();
  const changed = db.prepare(`UPDATE jobs SET status='running', attempts=attempts+1, progress_completed=0, updated_at=? WHERE id=? AND status='queued'`).run(now, row.id);
  if (changed.changes !== 1) return undefined;
  return db.prepare('SELECT * FROM jobs WHERE id=?').get(row.id) as unknown as JobRow;
}
function update(id: string, sql: string, ...args: (string | number | null)[]): void {
  db.prepare(sql).run(...args);
}

console.log('worker started');
while (!stopping) {
  heartbeat();
  const job = takeJob();
  if (!job) { await sleep(150); continue; }
  if (job.attempts <= job.fail_attempts) {
    if (job.attempts >= 3) {
      update(job.id, `UPDATE jobs SET status='failed', error='transient failure', result=NULL, updated_at=? WHERE id=?`, new Date().toISOString(), job.id);
    } else {
      update(job.id, `UPDATE jobs SET status='queued', progress_completed=0, retry_at=?, updated_at=? WHERE id=?`, Date.now() + 500, new Date().toISOString(), job.id);
    }
    continue;
  }
  let interrupted = false;
  for (let step = 1; step <= job.steps; step++) {
    await sleep(100);
    if (stopping) { interrupted = true; break; }
    update(job.id, `UPDATE jobs SET progress_completed=?, updated_at=? WHERE id=? AND status='running'`, step, new Date().toISOString(), job.id);
  }
  if (interrupted) break; // leave running for durable recovery on next startup
  update(job.id, `UPDATE jobs SET status='completed', result=?, error=NULL, progress_completed=?, updated_at=? WHERE id=? AND status='running'`,
    JSON.stringify({ output: job.input.toUpperCase() }), job.steps, new Date().toISOString(), job.id);
}
db.close();

