8	    body { font: 16px system-ui, sans-serif; max-width: 760px; margin: 2rem auto; padding: 0 1rem; color: #20242a; }
9	    form { display: grid; gap: .7rem; max-width: 32rem; margin-bottom: 1.5rem; }
10	    label { display: grid; gap: .25rem; } input, button { font: inherit; padding: .45rem; }
11	    #form-error { color: #a21b24; min-height: 1.3em; }
12	    #job-list { padding: 0; list-style: none; }
13	    [data-testid="job-item"] { border: 1px solid #ccd1d8; border-radius: .4rem; padding: .8rem; margin: .6rem 0; }
14	  </style>
15	</head>
16	<body>
17	  <h1>Job tracker</h1>
18	  <form data-testid="job-form" id="job-form">
19	    <label>Input <input data-testid="job-input" name="input" required maxlength="1000"></label>
20	    <label>Steps <input data-testid="job-steps" name="steps" type="number" min="1" max="20" value="5"></label>
21	    <label>Fail attempts <input data-testid="job-fail-attempts" name="failAttempts" type="number" min="0" max="5" value="0"></label>
22	    <button data-testid="job-submit" type="submit">Submit job</button>
23	    <div data-testid="form-error" role="alert"></div>
24	  </form>
25	  <h2>Jobs</h2>
26	  <ul data-testid="job-list" id="job-list"></ul>
27	  <script>
28	    const form = document.querySelector('[data-testid="job-form"]');
29	    const errorRegion = document.querySelector('[data-testid="form-error"]');
30	    const list = document.querySelector('[data-testid="job-list"]');
31	    function showError(data) {
32	      const err = data && data.error;
33	      errorRegion.textContent = err ? [err.message, ...(err.fields || []).map(f => `${f.field}: ${f.message}`)].join(' ') : 'Request failed.';
34	    }
35	    async function refresh() {
36	      try {
37	        const response = await fetch('/api/jobs');
38	        if (!response.ok) return;
39	        const data = await response.json();
40	        list.replaceChildren(...data.jobs.map(job => {
41	          const item = document.createElement('li'); item.dataset.testid = 'job-item'; item.dataset.jobId = job.id;
42	          const name = document.createElement('strong'); name.textContent = job.input; item.append(name, document.createTextNode(' — '));
43	          const status = document.createElement('span'); status.dataset.testid = 'job-status'; status.textContent = job.status; item.append(status);
44	          const progress = document.createElement('div'); progress.dataset.testid = 'job-progress'; progress.textContent = `${job.progress.completed}/${job.progress.total}`; item.append(progress);
45	          const result = document.createElement('div'); result.dataset.testid = 'job-result'; result.textContent = job.result ? job.result.output : (job.status === 'failed' ? job.error : ''); item.append(result);
46	          return item;
47	        }));
48	      } catch { /* a later poll will retry */ }
49	    }
50	    form.addEventListener('submit', async event => {
51	      event.preventDefault(); errorRegion.textContent = '';
52	      const payload = {
53	        input: form.elements.input.value,
54	        steps: Number(form.elements.steps.value),
55	        failAttempts: Number(form.elements.failAttempts.value)
56	      };
57	      try {
58	        const response = await fetch('/api/jobs', { method: 'POST', headers: { 'content-type': 'application/json' }, body: JSON.stringify(payload) });
59	        const data = await response.json();
60	        if (!response.ok) showError(data); else { form.elements.input.value = ''; refresh(); }
61	      } catch { errorRegion.textContent = 'Unable to submit job.'; }
62	    });
63	    refresh(); setInterval(refresh, 500);
64	  </script>
65	</body>
66	</html>
